import fs from 'node:fs';import path from 'node:path';import {pathToFileURL} from 'node:url';
const source=process.argv[2]==='live'?'.':'evidence/audit-followup-20261026/snapshot-arrival-fixed',label=process.argv[2]==='live'?'live':'fixed-snapshot';
const {Simulation}=await import(pathToFileURL(path.resolve(source,'src/simulation.js'))),{contractType}=await import(pathToFileURL(path.resolve(source,'src/config.js')));
function setup(){const s=new Simulation();s.units=[];s.player.retired=true;s.waveAt=1e9;for(const t of s.towers){t.x=100;t.cd=1e9;}const troop=(side,x,y,type='melee')=>{const u=s.spawn(side,type,0,1,x);Object.assign(u,{x,y,hp:1e7,maxHp:1e7,speed:0,cd:1e9});return u;};const hero=(id,x=0,y=0)=>{const p=s.makePlayer(id===3?1:0,false);p.classId=id;p.level=12;p.builds[id]=[1,1,1,1];const h=troop(p.side,x,y,contractType(id));s.contract(p,h.id);Object.assign(h,{hp:1e7,maxHp:1e7,cd:1e9,speed:0});return{p,h};};return{s,hero,troop};}
const out={source:label,at:new Date().toISOString(),frost:[],friend:[]};
for(const count of[1,2,3]){const {s,hero,troop}=setup(),casters=[hero(2,0,0),hero(2,1,0),hero(2,-1,0)].slice(0,count),victim=troop(1,0,3,'ranged');victim.cd=1.7;victim.targetId=casters[0].h.id;const shots=[],hits=[],oldProjectile=s.projectile.bind(s),oldDamage=s.damage.bind(s);s.projectile=function(a,t,...args){if(a.id===victim.id)shots.push({time:s.time,targetId:t.id});return oldProjectile(a,t,...args);};s.damage=function(a,t,n,basic,...rest){const before=t.hp,r=oldDamage(a,t,n,basic,...rest);if(a?.id===victim.id&&basic)hits.push({time:s.time,damage:before-t.hp,targetId:t.id});return r;};for(const c of casters){c.h.targetId=victim.id;s.cast(1,c.p);}const timeline=[];for(let i=0;i<160;i++){s.tick(.05);if(i%5===4)timeline.push({time:s.time,cd:victim.cd,remaining:Math.max(0,victim.cd-s.time),activeSlow:s.activeDebuffs(victim,'attackSpeedDown').map(d=>({ratio:d.ratio,until:d.until})),lastAttackAt:victim.lastAttackAt??null,victimHp:victim.hp});}out.frost.push({count,baseInterval:victim.interval,initialCd:1.7,shots,hits,firstShot:shots[0]??null,firstHit:hits[0]??null,timeline,values:s.skillValues});}
for(const id of[0,5]){const {s,hero,troop}=setup(),{p,h}=hero(id),e=troop(1,0,-15),ally=troop(0,2,0);h.speed=2;h.cd=0;s.setManualTarget(e.id,p);const beforeEnemy={manual:h.manualTargetId,target:h.targetId};s.setManualTarget(ally.id,p);const selectedFriend={manual:h.manualTargetId,target:h.targetId};s.tick(.05);out.friend.push({classId:id,aggro:h.aggro,beforeEnemy,selectedFriend,afterTick:{manual:h.manualTargetId,target:h.targetId,x:h.x,y:h.y},enemyId:e.id,allyId:ally.id});}
fs.writeFileSync(`evidence/audit-followup-20261026/minimal-bugs-${label}.json`,JSON.stringify(out,null,2));console.log(JSON.stringify({source:label,frost:out.frost.map(x=>({count:x.count,firstShot:x.firstShot,firstHit:x.firstHit,at475:x.timeline.find(t=>t.time>4.7&&t.time<4.8)})),friend:out.friend},null,2));
